/**
 * The hand-written SigV4 signer for Secrets Manager's GetSecretValue.
 *
 * @description Pinned against a signature AWS's own signer produced.
 *
 * The expected Authorization header below was generated by botocore's
 * SigV4Auth (AWS's Python SDK) for exactly this request — same ARN, region,
 * credentials, body and time — not copied from this module's output. A signer
 * bug fails here instead of as a 403 inside a customer's account.
 */

import { strict as assert } from "node:assert";
import { test } from "node:test";

import { signGetSecretValue } from "../lambda/lib/sigv4.js";

const ARN = "arn:aws:secretsmanager:ap-southeast-2:123456789012:secret:norg-AbCdEf";
const CREDS = {
  accessKeyId: "AKIDEXAMPLE",
  secretAccessKey: "wJalrXUtnFEMI/K7MDENG+bPxRfiCYEXAMPLEKEY",
  sessionToken: "SESSIONTOKENEXAMPLE",
};
const AT = new Date(Date.UTC(2026, 9, 16, 1, 2, 3));

test("the signature matches botocore's for the same request", () => {
  const { url, headers, body } = signGetSecretValue(ARN, "ap-southeast-2", CREDS, AT);
  assert.equal(url, "https://secretsmanager.ap-southeast-2.amazonaws.com/");
  assert.equal(body, JSON.stringify({ SecretId: ARN }));
  assert.equal(headers["x-amz-date"], "20261016T010203Z");
  assert.equal(
    headers.authorization,
    "AWS4-HMAC-SHA256 Credential=AKIDEXAMPLE/20261016/ap-southeast-2/secretsmanager/aws4_request, " +
      "SignedHeaders=content-type;host;x-amz-date;x-amz-security-token;x-amz-target, " +
      "Signature=1281e5de43aeaab32a99516316c503ae5dd7c9fe8565d7d4f16ab662d7f0645b",
  );
});

test("without a session token the token header is neither sent nor signed", () => {
  const { headers } = signGetSecretValue(ARN, "ap-southeast-2", { ...CREDS, sessionToken: null }, AT);
  assert.equal("x-amz-security-token" in headers, false);
  assert.match(headers.authorization, /SignedHeaders=content-type;host;x-amz-date;x-amz-target,/);
});
